const worksheetRows = `-- name: WorksheetRows :many

SELECT a.id, a.code, a.name, a.class,
  coalesce(sum(b.debit - b.credit) FILTER (WHERE NOT (b.month = $1 AND b.kind = 'penyesuaian')), 0)::numeric AS unadjusted,
  coalesce(sum(b.debit) FILTER (WHERE b.month = $1 AND b.kind = 'penyesuaian'), 0)::numeric AS adj_debit,
  coalesce(sum(b.credit) FILTER (WHERE b.month = $1 AND b.kind = 'penyesuaian'), 0)::numeric AS adj_credit
FROM ledger.balances b
JOIN ledger.accounts a ON a.id = b.account_id
WHERE b.company_id = $2 AND b.month <= $1
  AND (a.class <= 3 OR b.month >= $3)
GROUP BY a.id, a.code, a.name, a.class
ORDER BY a.code
`

type WorksheetRowsParams struct {
	Month       civil.Date
	CompanyID   uuid.UUID
	FiscalStart civil.Date
}

type WorksheetRowsRow struct {
	ID         uuid.UUID
	Code       string
	Name       string
	Class      int16
	Unadjusted money.Amount
	AdjDebit   money.Amount
	AdjCredit  money.Amount
}

// Laporan -----------------------------------------------------------------------
// Neraca lajur: saldo sebelum penyesuaian bulan @month, dan penyesuaian bulan itu.
func (q *Queries) WorksheetRows(ctx context.Context, arg WorksheetRowsParams) ([]WorksheetRowsRow, error) {
	rows, err := q.db.Query(ctx, worksheetRows, arg.Month, arg.CompanyID, arg.FiscalStart)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []WorksheetRowsRow
	for rows.Next() {
		var i WorksheetRowsRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.Name,
			&i.Class,
			&i.Unadjusted,
			&i.AdjDebit,
			&i.AdjCredit,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
